import { useMemo } from 'react'
import { useLoader } from '@react-three/fiber'
import {
  BufferAttribute,
  ImageBitmapLoader,
  MeshBasicMaterial,
  PlaneGeometry,
  SRGBColorSpace,
  Texture,
} from 'three'
import atlasData from './atlas.json'

/** Generated by art/build_atlas.py from the Qwen-Image sprite sheets (docs/ART.md). */
interface AtlasData {
  width: number
  height: number
  frames: Record<string, { x: number; y: number; w: number; h: number }>
}

const ATLAS = atlasData as AtlasData
export const ATLAS_URL = `${import.meta.env.BASE_URL}assets/atlas.webp`

export type FrameName = string

export function hasFrame(name: FrameName) {
  return name in ATLAS.frames
}

/** Width / height of a frame in pixels, so callers can keep the drawing's proportions. */
export function frameAspect(name: FrameName) {
  const f = ATLAS.frames[name]
  return f ? f.w / f.h : 1
}

/** ImageBitmapLoader (not TextureLoader) so the same code works in an OffscreenCanvas worker. */
export function useBitmapTexture(url: string) {
  const bitmap = useLoader(ImageBitmapLoader, url, (loader) => {
    loader.setOptions({ imageOrientation: 'flipY', premultiplyAlpha: 'none' })
  }) as ImageBitmap
  return useMemo(() => {
    const texture = new Texture(bitmap)
    texture.flipY = false
    texture.colorSpace = SRGBColorSpace
    texture.needsUpdate = true
    return texture
  }, [bitmap])
}

export function preloadAtlas() {
  useLoader.preload(ImageBitmapLoader, ATLAS_URL, (loader) => {
    loader.setOptions({ imageOrientation: 'flipY', premultiplyAlpha: 'none' })
  })
}

const geometries = new Map<string, PlaneGeometry>()

/** A unit quad whose UVs cover one atlas frame; shared by every sprite using that frame. */
export function frameGeometry(name: FrameName) {
  let geometry = geometries.get(name)
  if (geometry) return geometry
  const f = ATLAS.frames[name]
  geometry = new PlaneGeometry(1, 1)
  if (f) {
    const u0 = f.x / ATLAS.width
    const u1 = (f.x + f.w) / ATLAS.width
    const v1 = 1 - f.y / ATLAS.height
    const v0 = 1 - (f.y + f.h) / ATLAS.height
    // PlaneGeometry vertex order: top-left, top-right, bottom-left, bottom-right.
    geometry.setAttribute('uv', new BufferAttribute(new Float32Array([u0, v1, u1, v1, u0, v0, u1, v0]), 2))
  }
  geometries.set(name, geometry)
  return geometry
}

const materials = new Map<string, MeshBasicMaterial>()

export function spriteMaterial(texture: Texture, opacity = 1, color = '#ffffff') {
  const key = `${texture.id}:${opacity}:${color}`
  let material = materials.get(key)
  if (!material) {
    material = new MeshBasicMaterial({
      map: texture,
      transparent: true,
      opacity,
      color,
      depthWrite: false,
      alphaTest: 0.02,
    })
    materials.set(key, material)
  }
  return material
}
